fn starts_with(s: &[char], p: &[char]) -> bool {
    // If prefix is empty, always return true
    if p.is_empty() {
        return true;
    }
    
    // If sequence is shorter than prefix, cannot start with it
    if s.len() < p.len() {
        return false;
    }
    
    // Check each character up to prefix length
    for i in 0..p.len() {
        if s[i] != p[i] {
            return false;
        }
    }
    
    true
}

fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // Delegate to starts_with with slices for efficiency
    starts_with(v.as_slice(), p.as_slice())
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut result = Vec::new();
    
    for seq in xs {
        if has_prefix(&seq, &p) {
            result.push(seq);
        }
    }
    
    result
}